def simulation_interval(schedule, H):
    X = find_transient_end(schedule)
    k = find_period_multiple(schedule, X)
    return [0, X + k * H)

def general_sim_interval(tasks, delta):
    O_max = max(task.offset for task in tasks)
    H = lcm([task.T for task in tasks])
    return [0, O_max + 2 * H)

def ftp_sim_interval(tasks):
    S_n = sum(task.C for task in tasks)
    H = lcm([task.T for task in tasks])
    return [0, S_n + H)
